// Self-authored Base14-font fixtures are generated by the companion Python
// standard-library script. No embedded font asset or third-party PDF is needed.
#import <Foundation/Foundation.h>
#include "pdf_text_bridge.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>

static void check(NSString *path, size_t pages, size_t text, size_t json,
                  uint32_t status, const char *expected) {
    HZPdfTextResult result = {0};
    hz_pdf_text_extract(path.fileSystemRepresentation, pages, text, json, &result);
    assert(result.status == status);
    assert(result.json != NULL && result.length > 0);
    NSData *data = [NSData dataWithBytes:result.json length:result.length];
    NSDictionary *payload = [NSJSONSerialization JSONObjectWithData:data options:0 error:NULL];
    assert(payload != nil);
    if (expected != NULL) assert(strstr([payload[@"error"] UTF8String], expected) != NULL);
    hz_pdf_text_result_free(&result);
    assert(result.json == NULL && result.length == 0 && result.status == 0);
    hz_pdf_text_result_free(&result);
}

int main(int argc, const char *argv[]) {
    assert(argc == 2);
    @autoreleasepool {
        NSString *base = [NSString stringWithUTF8String:argv[1]];
        check([base stringByAppendingPathComponent:@"three_pages_blank_middle.pdf"], 1, 100000, 100000, 3, "page limit");
        check([base stringByAppendingPathComponent:@"latin_base14.pdf"], 100, 5, 100000, 3, "text size limit");
        check([base stringByAppendingPathComponent:@"latin_base14.pdf"], 100, 100000, 128, 3, "response size limit");
        check([base stringByAppendingPathComponent:@"latin_base14.pdf"], 100, 100000, 100000, 0, NULL);
        hz_pdf_text_extract(NULL, 0, 0, 0, NULL);
        hz_pdf_text_result_free(NULL);

        NSData *manifestData = [NSData dataWithContentsOfFile:[base stringByAppendingPathComponent:@"manifest.json"]];
        NSArray *manifest = [NSJSONSerialization JSONObjectWithData:manifestData options:0 error:NULL];
        assert(manifest != nil && manifest.count == 13);
        for (NSDictionary *entry in manifest) {
            NSString *name = entry[@"name"];
            NSString *path = [base stringByAppendingPathComponent:[name stringByAppendingString:@".pdf"]];
            HZPdfTextResult result = {0};
            hz_pdf_text_extract(path.fileSystemRepresentation, 16384, 16 * 1024 * 1024, 128 * 1024 * 1024, &result);
            if ([name isEqualToString:@"truncated_xref"]) {
                assert(result.status != 0);
            } else {
                assert(result.status == 0 && result.json != NULL);
                NSData *data = [NSData dataWithBytes:result.json length:result.length];
                NSDictionary *payload = [NSJSONSerialization JSONObjectWithData:data options:0 error:NULL];
                NSArray *pages = payload[@"pages"];
                assert(pages.count == [entry[@"pageCount"] unsignedIntegerValue]);
                for (NSUInteger index = 0; index < pages.count; index++) {
                    assert([pages[index][@"index"] unsignedIntegerValue] == index);
                }
                NSDictionary *singlePageExpected = @{
                    @"latin_base14": @"ASCII text 123.\nPunctuation: comma, colon; period.",
                    @"rotation_90": @"Rotated page 90 degrees.",
                    @"compressed_stream": @"Compressed text remains readable.",
                    @"broken_startxref": @"Recoverable malformed xref.",
                    @"two_columns": @"LEFT ONE\nLEFT TWO\nRIGHT ONE\nRIGHT TWO",
                };
                NSString *expectedText = singlePageExpected[name];
                if (expectedText != nil) assert([pages[0][@"text"] isEqualToString:expectedText]);
                if ([name isEqualToString:@"helvetica_standard"]) assert([pages[0][@"text"] isEqualToString:@"Helvetica standard encoding."]);
                if ([name isEqualToString:@"symbol"] || [name isEqualToString:@"symbol_default"]) assert([pages[0][@"text"] isEqualToString:@"αβγδπΣΩ"]);
                if ([name isEqualToString:@"latin_winansi"]) assert([pages[0][@"text"] isEqualToString:@"Café déjà vu. € euro – dash."]);
                if ([name isEqualToString:@"latin_macroman"]) assert([pages[0][@"text"] isEqualToString:@"Café résumé."]);
                if ([name isEqualToString:@"three_pages_blank_middle"]) {
                    assert([pages[0][@"text"] isEqualToString:@"PAGE ONE"]);
                    assert([pages[1][@"text"] length] == 0);
                    assert([pages[2][@"text"] isEqualToString:@"PAGE THREE"]);
                }
                if ([name isEqualToString:@"long_41_pages"]) {
                    for (NSUInteger index = 0; index < pages.count; index++) assert(([pages[index][@"text"] isEqualToString:[NSString stringWithFormat:@"Page %lu text", (unsigned long)index + 1]]));
                }
            }
            hz_pdf_text_result_free(&result);
        }
        check([base stringByAppendingPathComponent:@"encrypted-native.pdf"], 100, 100000, 100000, 2, "password");
        check([base stringByAppendingPathComponent:@"malformed-native.pdf"], 100, 100000, 100000, 1, "Cannot open");
        NSArray *generatedNames = @[@"english-native", @"japanese-native", @"mixed-native", @"empty-native", @"scan-native"];
        for (NSString *name in generatedNames) {
            NSString *path = [base stringByAppendingPathComponent:[name stringByAppendingString:@".pdf"]];
            HZPdfTextResult result = {0};
            hz_pdf_text_extract(path.fileSystemRepresentation, 16384, 16 * 1024 * 1024, 128 * 1024 * 1024, &result);
            assert(result.status == 0 && result.json != NULL);
            NSData *data = [NSData dataWithBytes:result.json length:result.length];
            NSDictionary *payload = [NSJSONSerialization JSONObjectWithData:data options:0 error:NULL];
            NSArray *pages = payload[@"pages"];
            assert(pages.count == ([name isEqualToString:@"mixed-native"] ? 3 : 1));
            if ([name isEqualToString:@"english-native"]) {
                NSString *text = pages[0][@"text"];
                for (NSString *line in @[@"Hazakura PDF import fixture.", @"English punctuation: comma, period.", @"The source remains unchanged."]) assert([text containsString:line]);
            }
            if ([name isEqualToString:@"japanese-native"]) {
                NSString *text = pages[0][@"text"];
                for (NSString *line in @[@"葉桜の日本語テキスト。", @"句読点、英数字123を確認する。", @"原稿は変更しない。"]) assert([text containsString:line]);
            }
            if ([name isEqualToString:@"mixed-native"]) {
                assert([pages[0][@"text"] containsString:@"日本語とEnglish 123。"]);
                assert([pages[1][@"text"] length] == 0);
                assert([pages[2][@"text"] containsString:@"終わり End."]);
            }
            if ([name isEqualToString:@"empty-native"] || [name isEqualToString:@"scan-native"]) assert([pages[0][@"text"] length] == 0);
            hz_pdf_text_result_free(&result);
        }
        puts("PDFKit bridge: 20 fixtures (Japanese/scan/locked included), limits, ownership and NULL checks passed.");
    }
    return 0;
}
